import * as React from 'react'

import styles from './primitives.module.scss'

/**
 * Calls `onDismiss` on Escape or an outside pointer press. Nested layers can
 * opt out by preventing the event default.
 */
export function DismissableLayer({
  children,
  onDismiss,
  enabled = true,
}: {
  children: React.ReactNode
  onDismiss: () => void
  enabled?: boolean
}) {
  const ref = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (!enabled) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.defaultPrevented) return
      event.preventDefault()
      onDismiss()
    }
    const onPointerDown = (event: PointerEvent) => {
      const node = ref.current
      if (!node || node.contains(event.target as Node)) return
      onDismiss()
    }
    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown, true)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown, true)
    }
  }, [enabled, onDismiss])

  return (
    <div ref={ref} className={styles.layer}>
      {children}
    </div>
  )
}

import * as React from 'react'

import styles from './primitives.module.scss'

type Props = { children: React.ReactNode; fallback?: React.ReactNode }
type State = { error: Error | null }

/** Isolates a failing widget or chart so the rest of the page keeps working. */
export class ErrorBoundary extends React.Component<Props, State> {
  state: State = { error: null }

  static getDerivedStateFromError(error: Error): State {
    return { error }
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('Vorzela UI error boundary:', error, info.componentStack)
  }

  render() {
    if (this.state.error) {
      return (
        this.props.fallback ?? (
          <div role="alert" className={styles.error}>
            Something went wrong in this section.
          </div>
        )
      )
    }
    return this.props.children
  }
}

import * as React from 'react'

import { useReducedMotion } from '~/hooks/use-reduced-motion'
import { cx } from '~/lib/cx'
import styles from './primitives.module.scss'

/** Fade and rise on mount. Exits are intentionally not animated. */
export function FadeIn({
  children,
  className,
  delay = 0,
  duration = 240,
}: {
  children: React.ReactNode
  className?: string
  delay?: number
  duration?: number
}) {
  const reduced = useReducedMotion()

  return (
    <div
      className={cx(styles.fade, reduced && styles.fadeReduced, className)}
      style={
        {
          '--vz-fade-duration': `${reduced ? 0 : duration}ms`,
          '--vz-fade-delay': `${reduced ? 0 : delay}ms`,
        } as React.CSSProperties
      }
    >
      {children}
    </div>
  )
}

import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './primitives.module.scss'

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
  '[contenteditable="true"]',
].join(',')

/** Traps Tab focus and restores focus on unmount. */
export function FocusTrap({
  children,
  className,
  active = true,
  restoreFocus = true,
}: {
  children: React.ReactNode
  className?: string
  active?: boolean
  restoreFocus?: boolean
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const previous = React.useRef<HTMLElement | null>(null)

  React.useEffect(() => {
    if (!active) return
    const node = ref.current
    if (!node) return
    previous.current = document.activeElement as HTMLElement | null

    const items = node.querySelectorAll<HTMLElement>(FOCUSABLE)
    ;(items[0] ?? node).focus()

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return
      const focusable = Array.from(node.querySelectorAll<HTMLElement>(FOCUSABLE))
      if (focusable.length === 0) {
        event.preventDefault()
        return
      }
      const first = focusable[0]!
      const last = focusable[focusable.length - 1]!
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault()
        first.focus()
      }
    }

    node.addEventListener('keydown', onKeyDown)
    return () => {
      node.removeEventListener('keydown', onKeyDown)
      if (restoreFocus) previous.current?.focus()
    }
  }, [active, restoreFocus])

  return (
    <div ref={ref} className={cx(styles.trap, className)} tabIndex={-1}>
      {children}
    </div>
  )
}

import * as React from 'react'
import { createPortal } from 'react-dom'

const subscribe = () => () => {}
const getClientSnapshot = () => true
const getServerSnapshot = () => false

/** Renders children into `document.body`. SSR-safe. */
export function Portal({
  children,
  container,
}: {
  children: React.ReactNode
  container?: HTMLElement | null
}) {
  const mounted = React.useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  )
  if (!mounted) return null
  return createPortal(children, container ?? document.body)
}

@use 'styles' as vz;

.layer {
  display: contents;
}

.trap {
  outline: none;
}

.fade {
  animation: vz-fade-in var(--vz-fade-duration, 240ms) vz.ease('out')
    var(--vz-fade-delay, 0ms) both;
}

.fade-reduced {
  animation: none;
}

.skip {
  position: fixed;
  top: vz.space(4);
  left: vz.space(4);
  z-index: vz.z('toast');
  padding: vz.space(2) vz.space(4);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('md');
  background: vz.color('primary');
  color: vz.color('primary-foreground');
  font-size: vz.font-size('sm');
  font-weight: 600;
  text-decoration: none;
  box-shadow: vz.elevation(2);
  transform: translateY(-200%);

  &:focus-visible {
    transform: none;
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: 2px;
  }
}

.sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.error {
  padding: vz.space(4);
  border: 1px solid vz.color('destructive', 0.3);
  border-radius: vz.radius('lg');
  background: vz.color('destructive', 0.06);
  color: vz.color('destructive');
  font-size: vz.font-size('sm');
  line-height: 1.5;
}

@keyframes vz-fade-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './primitives.module.scss'

/** First focusable control on the page; jumps to main content. */
export function SkipLink({
  href = '#main',
  children = 'Skip to content',
  className,
}: {
  href?: string
  children?: React.ReactNode
  className?: string
}) {
  return (
    <a href={href} className={cx(styles.skip, className)}>
      {children}
    </a>
  )
}

import * as React from 'react'

import { cx } from '~/lib/cx'
import styles from './primitives.module.scss'

/** Screen-reader-only content. */
export function VisuallyHidden({
  className,
  ...props
}: React.ComponentProps<'span'>) {
  return <span className={cx(styles.sr, className)} {...props} />
}
